package com.corecs.solid.rules;import com.corecs.solid.model.*;import java.util.*;public class SrpRule implements SolidRule{public List<Issue> analyze(List<ClassInfo> cs){List<Issue> o=new ArrayList<>();for(var c:cs)if(!c.interfaceType()&&c.methods().size()>=6){o.add(new Issue("SRP","Potential",c.name(),"Many responsibilities may be concentrated in one class","The class exposes many methods. Method count alone cannot prove an SRP violation, but it is a useful review signal.","Group methods by business responsibility and consider focused services."));}return o;}}
